*{box-sizing:border-box} :root{font-family:'DM Sans',sans-serif;color:#f8f6ef;background:#052f3a;font-synthesis:none;font-optical-sizing:auto;font-weight:400;--mint:#9ae6d2;--cream:#f6f0de;--ink:#123b43;--gold:#e4c47d}body{margin:0;min-width:320px;min-height:100vh;background:radial-gradient(ellipse at 42% 48%,#155261 0,#0a414e 42%,#062f3a 100%);overflow-x:hidden}.app-shell{max-width:1512px;margin:auto;min-height:100svh;padding:0 40px 18px}.topbar{height:74px;border-bottom:1px solid #ffffff22;display:flex;align-items:center;justify-content:space-between;position:relative;z-index:2}.brand{display:flex;align-items:center;gap:11px;color:#f4f1e7;text-decoration:none;font-size:13px;font-weight:600;letter-spacing:2px}.brand b{font-weight:400;color:#a6e2d4}.brand-mark{width:31px;height:31px;border:1px solid #9de2d2;border-radius:50%;display:grid;place-items:center;color:#a9eedb;font-size:19px}.season-pill{font-size:10px;font-weight:700;letter-spacing:1.55px;color:#e5d7ac;background:#ffffff0b;border:1px solid #ffffff20;border-radius:30px;padding:10px 15px}.live-dot{display:inline-block;width:6px;height:6px;margin:0 8px 1px 0;background:#a2e8c9;border-radius:50%;box-shadow:0 0 9px #a2e8c9}.pill-divider{color:#ffffff55;margin:0 7px}.icon-btn,.round-btn{border:1px solid #ffffff37;background:#ffffff08;color:#eee9d9;border-radius:50%;cursor:pointer;transition:.2s}.sound-btn{width:37px;height:37px;font-size:17px}.sound-btn:hover,.round-btn:hover{background:#ffffff20;transform:translateY(-2px)}.game-layout{display:grid;grid-template-columns:minmax(0,1.48fr) minmax(355px,.82fr);gap:30px;padding:27px 0 0;max-width:1320px;margin:auto}.stage-wrap{min-width:0}.stage-topline{display:flex;justify-content:space-between;align-items:center;padding:0 10px 15px}.eyebrow{font-size:9px;letter-spacing:2px;font-weight:700;color:#9bd8c9}.stage-topline h1{font-family:'Playfair Display',serif;font-size:30px;line-height:1.15;font-weight:600;margin:5px 0 0;color:#f5f0e2}.stage-topline h1 em{color:#b7e7d8;font-weight:600}.stage-actions{display:flex;gap:9px}.round-btn{width:37px;height:37px;font-size:20px}.stage{position:relative;height:min(70vh,680px);min-height:480px;overflow:hidden;border:1px solid #ffffff20;border-radius:7px;background:radial-gradient(ellipse at 50% 40%,#36848b 0,#1d6876 32%,#104f60 69%,#0a3b4b 100%);box-shadow:0 23px 65px #001c243b,inset 0 0 50px #082c3b55;touch-action:none}.water-glow{position:absolute;width:60%;height:95%;left:20%;top:-19%;background:radial-gradient(ellipse,#d1edc244 0,transparent 68%);filter:blur(9px);pointer-events:none}.water-lines{position:absolute;inset:0;opacity:.2;background:repeating-linear-gradient(175deg,transparent 0 56px,#b6e4d422 58px,transparent 60px 110px);mask-image:linear-gradient(to bottom,transparent,#000 24%,#000 82%,transparent)}#character-mount{position:absolute;inset:0;z-index:3;touch-action:none}#character-mount canvas{display:block;width:100%;height:100%;cursor:grab}#character-mount canvas:active{cursor:grabbing}.stage-label{position:absolute;top:21px;left:22px;color:#d4ede0;font-size:9px;font-weight:700;letter-spacing:1.65px;z-index:4}.stage-star{color:#edce82;font-size:15px;margin-right:6px}.stage-caption{position:absolute;bottom:37px;left:0;right:0;z-index:4;display:flex;align-items:center;justify-content:center;gap:13px;color:#ecdeae;font-size:9px;letter-spacing:2px;font-weight:700}.caption-line{height:1px;width:34px;background:#d7c68b88}.stage-counter{position:absolute;right:21px;top:50%;z-index:4;display:grid;gap:8px}.counter-dot{width:5px;height:5px;border-radius:50%;background:#ffffff55}.counter-dot.active{background:#e8d494;box-shadow:0 0 7px #e8d494}.drag-hint{position:absolute;bottom:19px;left:21px;z-index:4;color:#c6e4d8aa;font-size:8px;letter-spacing:1.35px}.drag-hint span{font-size:15px;margin-right:5px}.pedestal{position:absolute;bottom:20px;left:50%;transform:translateX(-50%);width:188px;height:18px;border-radius:50%;background:radial-gradient(ellipse,#f4d897a8 0,#d9ac5b60 35%,transparent 73%);z-index:1}.pedestal div{position:absolute;left:35px;right:35px;top:-8px;height:12px;border:1px solid #e6ca8b69;border-radius:50%;background:linear-gradient(#8ecac052,#25717c88)}.bottom-note{text-align:center;color:#a9d8cbb0;font-family:'Playfair Display',serif;font-size:12px;padding:14px}.bottom-note span{color:#e9d39a;margin:0 6px}.bubbles{position:absolute;inset:0;overflow:hidden;pointer-events:none}.bubbles i{position:absolute;bottom:-20px;left:15%;width:7px;height:7px;border:1px solid #cdf8ed77;border-radius:50%;animation:rise 7s linear infinite}.bubbles i:nth-child(2){left:29%;width:4px;height:4px;animation-duration:9s;animation-delay:2s}.bubbles i:nth-child(3){left:72%;width:9px;height:9px;animation-duration:8s;animation-delay:1s}.bubbles i:nth-child(4){left:88%;width:5px;height:5px;animation-duration:10s;animation-delay:4s}.bubbles i:nth-child(5){left:53%;width:4px;height:4px;animation-duration:8s;animation-delay:3s}.bubbles i:nth-child(6){left:8%;width:3px;height:3px;animation-duration:10s;animation-delay:5s}.bubbles i:nth-child(7){left:63%;width:6px;height:6px;animation-duration:9s;animation-delay:2s}.bubbles i:nth-child(8){left:39%;width:3px;height:3px;animation-duration:11s;animation-delay:4s}@keyframes rise{to{transform:translateY(-620px);opacity:0}}.reef{position:absolute;bottom:0;height:112px;width:100px;z-index:2;opacity:.7}.reef-left{left:-10px}.reef-right{right:-8px;transform:scaleX(-1)}.reef span{position:absolute;bottom:0;width:19px;height:78px;border-radius:90% 15% 0 0;background:linear-gradient(90deg,#d6747188,#efaa8188);transform:rotate(-8deg);transform-origin:bottom}.reef span:nth-child(2){height:100px;left:22px;width:15px;background:#c87c9b99;transform:rotate(12deg)}.reef span:nth-child(3){height:57px;left:45px;width:23px;background:#dfa87999;transform:rotate(-20deg)}.reef span:nth-child(4){height:82px;left:70px;width:17px;background:#a37aab99;transform:rotate(19deg)}.wardrobe{background:#f6f2e7;border-radius:8px;color:#173c42;padding:23px 24px 16px;box-shadow:0 20px 60px #0019202b;display:flex;flex-direction:column;min-height:610px}.wardrobe-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}.wardrobe .eyebrow{font-size:8px;color:#629b8e}.wardrobe h2{font-family:'Playfair Display',serif;font-size:24px;line-height:1.1;margin:4px 0 0;color:#153a40;font-weight:600}.reset-btn{border:0;background:transparent;color:#68837d;font-size:9px;letter-spacing:1.2px;font-weight:700;cursor:pointer;padding:9px}.reset-btn span{font-size:17px;margin-left:5px;vertical-align:-2px}.challenge{display:flex;align-items:center;gap:13px;padding:12px 14px;border:1px solid #dfe7dc;background:linear-gradient(110deg,#edf2e8,#f5eddb);border-radius:5px;position:relative;overflow:hidden}.challenge-icon{width:34px;height:34px;background:#dbe9d8;border:1px solid #ceded1;border-radius:50%;display:grid;place-items:center;font-size:23px;color:#619987}.challenge-label{display:block;font-size:7px;letter-spacing:1.45px;font-weight:700;color:#79958a;margin-bottom:3px}.challenge strong{display:block;font-family:'Playfair Display',serif;font-size:15px;color:#234c4e;font-weight:600}.challenge small{font-size:9px;color:#7e9286;display:block;margin-top:3px}.challenge-sparkle{position:absolute;right:15px;top:10px;color:#d5b66e;font-size:14px}.category-tabs{display:grid;grid-template-columns:repeat(4,1fr);margin:18px 0 13px;border-bottom:1px solid #d9e2d9}.tab{border:0;border-bottom:2px solid transparent;background:transparent;padding:0 2px 10px;color:#879790;font-size:8px;letter-spacing:1px;font-weight:700;cursor:pointer;transition:.18s}.tab span{display:block;font-size:18px;margin:0 auto 4px;color:#829991}.tab.active{border-color:#388a7b;color:#1f625b}.tab.active span{color:#3f9887}.options-header{display:flex;justify-content:space-between;align-items:center;font-size:8px;font-weight:700;letter-spacing:1.3px;color:#69827a;margin:0 0 10px}.options-header span:last-child{font-size:7px;color:#a0aaa2}.options-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px;min-height:105px}.option-card{border:1px solid #dce5dc;border-radius:5px;background:#fbfaf4;min-height:96px;padding:7px 4px 6px;cursor:pointer;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:5px;color:#567169;transition:all .18s;position:relative}.option-card:hover{transform:translateY(-2px);border-color:#84b6a5}.option-card.selected{background:#edf5eb;border:1.5px solid #559a89;box-shadow:0 0 0 2px #559a8918}.option-card.selected:after{content:'✓';position:absolute;right:5px;top:3px;color:#358575;font-size:10px;font-weight:700}.swatch{width:43px;height:43px;border-radius:50%;position:relative;box-shadow:inset -7px -6px 12px #163c3b22,inset 4px 5px 9px #ffffff5b,0 2px 5px #183d3b20;overflow:hidden;border:1px solid #183f3b18}.swatch:after{content:'';position:absolute;inset:4px;border:1px solid #ffffff59;border-radius:50%}.option-name{font-size:8px;line-height:1.1;text-align:center;white-space:nowrap;letter-spacing:.1px}.style-score{margin-top:auto;padding-top:16px}.score-top{display:flex;justify-content:space-between;align-items:center;font-size:8px;letter-spacing:1.2px;font-weight:700;color:#6b827a}.score-top strong{font-family:'Playfair Display',serif;font-size:19px;color:#245a54;letter-spacing:0}.score-top small{font:9px 'DM Sans',sans-serif;color:#9aa8a0;margin-left:2px}.score-track{height:4px;background:#dfe7dc;border-radius:5px;margin:6px 0 8px;overflow:hidden}.score-track i{display:block;height:100%;width:72%;background:linear-gradient(90deg,#7ec6a6,#ddc479);border-radius:5px;transition:width .5s}.score-caption{display:flex;align-items:center;gap:6px;color:#87978c;font-size:9px}.score-caption span:first-child{color:#c7a75e;font-size:12px}.complete-btn{margin-top:14px;border:0;border-radius:4px;background:#1a5555;color:#f7f0dd;display:flex;align-items:center;justify-content:center;gap:22px;height:45px;font:700 9px 'DM Sans',sans-serif;letter-spacing:1.5px;cursor:pointer;transition:.2s;box-shadow:0 5px 12px #1a55552b}.complete-btn:hover{background:#236e67;transform:translateY(-1px)}.button-arrow{font-size:17px;color:#e5cb8e}.wardrobe-foot{text-align:center;color:#9aaba0;font-size:7px;letter-spacing:1.5px;margin-top:13px}.wardrobe-foot span{color:#d2b776;margin:0 4px}.toast{position:fixed;left:50%;bottom:24px;z-index:20;transform:translate(-50%,20px);opacity:0;pointer-events:none;background:#f7f1df;color:#1c5550;border:1px solid #d9c888;padding:12px 19px;border-radius:4px;box-shadow:0 8px 30px #001d2866;font-size:12px;transition:.25s}.toast.show{opacity:1;transform:translate(-50%,0)}
@media(max-width:900px){.app-shell{padding:0 22px 18px}.game-layout{grid-template-columns:minmax(0,1fr) minmax(315px,.82fr);gap:18px}.wardrobe{padding:19px 17px 14px}.stage{min-height:450px;height:67vh}.stage-topline h1{font-size:26px}}
@media(max-width:700px){.app-shell{padding:0 12px calc(13px + env(safe-area-inset-bottom))}.topbar{height:58px}.brand{font-size:11px;gap:7px}.brand-mark{width:27px;height:27px}.season-pill{font-size:7px;padding:8px 9px;letter-spacing:1px}.sound-btn{width:32px;height:32px}.game-layout{display:flex;flex-direction:column;gap:0;padding-top:13px}.stage-topline{padding:0 5px 10px}.stage-topline h1{font-size:23px}.stage-topline .eyebrow{font-size:8px}.stage-actions{gap:7px}.round-btn{width:33px;height:33px}.stage{height:48svh;min-height:325px;max-height:490px;border-radius:6px}.stage-label{top:14px;left:13px;font-size:7px}.drag-hint{bottom:15px;left:13px;font-size:7px}.stage-caption{bottom:24px;font-size:7px}.caption-line{width:22px}.pedestal{bottom:13px;transform:translateX(-50%) scale(.75)}.stage-counter{right:12px}.reef{transform:scale(.75);transform-origin:bottom left}.reef-right{transform:scaleX(-1) scale(.75);transform-origin:bottom right}.bottom-note{display:none}.wardrobe{margin-top:12px;padding:15px 15px 12px;min-height:unset}.wardrobe-heading{margin-bottom:11px}.wardrobe h2{font-size:21px}.challenge{padding:9px 11px}.challenge-icon{width:30px;height:30px}.challenge strong{font-size:14px}.category-tabs{margin:13px 0 10px}.tab{padding-bottom:7px}.tab span{font-size:16px}.options-grid{min-height:86px;gap:7px}.option-card{min-height:80px;padding:5px 2px}.swatch{width:35px;height:35px}.option-name{font-size:7px}.style-score{padding-top:10px}.complete-btn{height:40px;margin-top:10px}.wardrobe-foot{margin-top:9px}.toast{bottom:calc(16px + env(safe-area-inset-bottom));white-space:nowrap}}
@media(max-width:380px){.app-shell{padding-left:9px;padding-right:9px}.wardrobe{padding-left:11px;padding-right:11px}.season-pill{padding:7px 6px}.stage{min-height:300px}.option-name{font-size:6.5px}.options-grid{gap:5px}}
@media(min-width:701px) and (max-height:780px){.stage{height:60vh;min-height:440px}.wardrobe{min-height:550px}}
